import { toast as sonnerToast } from '../sonner'
import { AnythingToast } from '../screens/project/components/AnythingToast'
import { DEFAULT_TOAST_DURATION } from '../constants'
import { LucideIcon } from 'lucide-react-native'

export type AnythingToastVariant = 'success' | 'error' | 'default'

interface ShowAnythingToastProps {
	message: string
	variant?: AnythingToastVariant
	duration?: number
	customIcon?: LucideIcon
}

export const toast = {
	show: ({
		message,
		variant = 'default',
		duration = DEFAULT_TOAST_DURATION,
		customIcon
	}: ShowAnythingToastProps) => {
		sonnerToast.dismiss()
		const toastId = sonnerToast.custom(
			<AnythingToast
				message={message}
				variant={variant}
				customIcon={customIcon}
			/>,
			{
				duration,
				dismissible: duration === Infinity ? false : true
			}
		)
		return toastId
	},
	hide: (toastId: string | number) => {
		sonnerToast.dismiss(toastId)
	},
	hideAll: () => {
		sonnerToast.dismiss()
	}
}
